"""Document the corrected two-fighter layout and its native demonstrations."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1];CH=ROOT/'sprite-fighter/characters'
MOVES={
 'prince': [('Prince','Check Ball','Purple Slide','Ruffle Counter','Baseline Cut','Game, Blouses','Breakfast Is Served'),('Rick James','Unity Slap','Platform Rush','Couch Surf','Couch Crusher','Unity Tour','Five Fingers')],
 'tyrone': [('Tyrone Biggums','Quick Rush','Panic Lunge','Backpedal','Floor Scramble','Scramble City','Lights Out'),('Negan','The Whistle','Take a Knee','Swing and a Miss','Business Meeting','Collection Day','The Last Laugh')]}
SIGNATURES={
 'Prince':('Ankle-Breaker','Bouncing basketball plus a crossover retreat and chase.','Purple Skyhook','A hanging aerial shot fired steeply downward.'),
 'Rick James':('Couch Surfboard','Ride a moving couch into a low hit.','Platform Pogo','A diving stomp rebounds upward only when it hits.'),
 'Tyrone Biggums':('Pocket Sand Panic','A sand cone causes long hit stun while Tyrone scrambles backward.','Wrong Way!','A forward-back-forward air dash ends in a frantic strike.'),
 'Negan':('Lucille’s Verdict','Hold skill + heavy to charge; release after the windup, or reach full charge for 145 damage.','Dead Weight','A heavy falling bat smash with a long, vulnerable landing.')}
style='''*{box-sizing:border-box}body{margin:0;background:#0b1120;color:#eef1ff;font:16px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:30px 22px}h1{font-size:clamp(32px,5vw,58px);line-height:1.12}h2{font-size:25px}p{color:#b9c8e4}a{color:#a4d1ff}.eyebrow{color:#d9a5ff;font-size:12px;letter-spacing:.15em;text-transform:uppercase}article{background:#141f36;border:1px solid #3a4968;border-radius:16px;padding:22px;margin:22px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}img{max-width:100%;border-radius:10px}kbd{background:#26385a;border:1px solid #7285ab;border-radius:5px;padding:3px 8px;color:#ffdf9a}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #354365}.status{color:#91e0bb}.small{font-size:13px}.links{display:flex;flex-wrap:wrap;gap:18px}canvas{width:100%;background:radial-gradient(ellipse at bottom,#34446d,#10172a);border-radius:14px}button{background:#253653;border:1px solid #6e80a1;color:#eef1ff;padding:9px 15px;border-radius:8px;cursor:pointer;margin:8px}'''
cards=[]
for slug in ['prince','tyrone']:
    source=CH/slug;report=json.loads((source/'paired-build-report.json').read_text());names=report['forms'];moves=MOVES[slug]
    runtime=source/'paired-runtime-validation.json';r=json.loads(runtime.read_text()) if runtime.exists() else {}
    status=f"{r.get('passed',0)} pairing checks passed; {r.get('failed',0)} failed" if r.get('status')=='Complete' else 'Pairing checks in progress'
    table='| Form | Skill | Toward + skill | Away + skill | Down + skill |\n|---|---|---|---|---|\n'+''.join('| '+' | '.join(row[:5])+' |\n' for row in moves)
    text=f'''# {names[0]} / {names[1]} - one fighter, two forms

The user's corrected roster has exactly two Chappelle fighters:
Prince <-> Rick James, and Tyrone Biggums <-> Negan.
This slot starts as {names[0]}; transform to {names[1]} and press again to return.

| Action | Player 1 | Player 2 |
|---|---|---|
| Move / jump / crouch | Arrows | I/J/K/L |
| Light / medium / heavy | Z/X/C | F/G/H |
| Skill | A | R |
| Super | S | T |
| Ultimate | D | Y |
| Throw | Q | [ |
| Transform / return | W | ] |
| Guard | Away / down-away | Away / down-away |

{table}
Directions follow the opponent. Crouching and jumping change normals.
The transformation is free while grounded and controllable, takes 42 ticks,
switches at tick 18 and has a 90-tick cooldown from reveal. Health and remaining
meter stay shared. It changes the complete kit and the matching effects rather
than only the outfit. Each slot switches only between its two assigned forms.

'''
    for row in moves:text+=f"- {row[0]} super: **{row[5]}**, 1000 meter / 620 damage. Ultimate: **{row[6]}**, 2000 meter / 950 damage.\n"
    text+='\nSupers/ultimates use guardable medium/close starters. Their confirmed sequences last four/seven seconds, resolving damage once. A block or whiff prevents the cinematic. Maximum health is 1000 and meter 3000; launchers start full with no timer.\n\n'
    if slug=='prince':text+='Prince: quarter-circle toward + attack fires a basketball; quarter-circle away + light/medium/heavy uses feint/slide/counter. Check Ball branches with light/medium/heavy into ball/side switch/rejection. Rick: quarter-circle toward + attack uses Cold Blooded strengths; quarter-circle away + light/heavy retreats, medium rushes. Forward-down-down-forward + heavy uses the current form anti-air.\n'
    else:text+='Tyrone: quarter-circle toward + light/medium/heavy uses rush/lunge/floor scramble; quarter-circle away + light/heavy backpedals, medium scrambles. Negan: quarter-circle toward + attack uses the three bat strengths; quarter-circle away + light/medium/heavy uses feint/low/grab. Whistle stance branches with light/medium/heavy into bat/low/anti-air. Forward-down-down-forward + heavy uses the current form anti-air.\n'
    text+='\nFirst-pass key-pose art and shared drawings are retained. More in-betweens, portraits, voice and cinematic polish remain. Existing art and its exact imagegen prompts are preserved.\n'
    signature_rows=''
    text+='\nPose proportions are calibrated individually with foot and pelvis anchors, including both transformation forms and reactions. [Before/after comparison](../chappelle/scale-review.html).\n\n## New signature moves\n\nOn the ground, press **skill + heavy together** (P1 **A + C**, P2 **R + H**). In the air, press **skill** (P1 **A**, P2 **R**). These moves cost no meter and remain vulnerable.\n\n'
    for name in names:
        ground,ground_description,air,air_description=SIGNATURES[name]
        text+=f'- **{name}: {ground}** — {ground_description} Air: **{air}** — {air_description}\n'
        signature_rows+=f'<tr><td>{name}</td><td><strong>{ground}</strong><br>{ground_description}</td><td><strong>{air}</strong><br>{air_description}</td></tr>'
    text+='\nAuthored ultimates: Prince rises with a plate of pancakes and dunks it onto the opponent\'s head. Rick asks "What did the five fingers say to the face?" before the huge slap. Tyrone mists the opponent\'s face, leaves them dizzy, then lands the knockout punch. Negan approaches a kneeling opponent in a night clearing, raises Lucille and strikes as the camera cuts to black, revealing a grounded aftermath. Damage and meter costs remain 620/1000 for supers and 950/2000 for ultimates.\n'
    (source/'CONTROLS.md').write_text(text)
    (source/'README.md').write_text(f'# {names[0]} / {names[1]}\n\nOne roster slot. W as P1 or ] as P2 transforms and returns, free with shared health/meter.\n\n[Controls](CONTROLS.md) · [Two-fighter hub](../chappelle/review.html) · [Pair review](review.html) · [Native checks](paired-runtime-validation.json) · [Verification](paired-verification.json).\n\n{status}. Both existing kits, key poses and effects are retained. Builder: scripts/build-chappelle-pairs.py. Prior three-slot components/reports are archived under characters/chappelle/components-v1 and are not the active roster layout.\n')
    pose_data={k:dict(m,file='../../'+m['file'].replace('\\','/').removeprefix('sprite-fighter/')) for k,m in report['sprites'].items()}
    rows=''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row[:5])+'</tr>' for row in moves)
    html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{names[0]} / {names[1]}</title><style>{style}</style><main><div class="eyebrow">Chappelle · Two-fighter roster · Updated pairing</div><h1>{names[0]} ⇄ {names[1]}</h1><p>One fighter. Two assigned forms. Press <kbd>W</kbd> as Player 1 or <kbd>]</kbd> as Player 2 to transform and return.</p><p class="status">{status}</p><div class="links"><a href="../chappelle/review.html">Both fighters</a><a href="CONTROLS.md">Controls</a><a href="paired-runtime-validation.json">Pairing checks</a><a href="paired-verification.json">Package verification</a></div><h2>Both looks at gameplay scale</h2><canvas width="1000" height="460"></canvas><button id="toggle">Preview {names[1]}</button><p id="form">{names[0]}</p><article><h2>Skills change with the form</h2><table><tr><th>Form</th><th>Skill</th><th>Toward</th><th>Away</th><th>Down</th></tr>{rows}</table></article><article><h2>Actual transformation and combat replay</h2><img src="paired-replay-v2.gif" alt="Native gameplay showing {names[0]} transforming into {names[1]} and returning"><p class="small">Recorded from the real engine. Transform, alternate special and super, return, base special and ultimate. <a href="paired-preview-report.json">Frame provenance</a>.</p></article><article><h2>Shared resources, full movesets</h2><p>The free 42-tick transformation switches at tick 18 and shares health and meter. The 90-tick cooldown prevents immediate repeated switching. Each form keeps its own specials, super and ultimate. Supers cost 1000 and deal 620 on confirmation; ultimates cost 2000 and deal 950. Starters remain guardable.</p></article><p>First playable art uses key poses and shared drawings. More animation, portraits and cinematic polish remain.</p><script>const data={json.dumps(pose_data)},names={json.dumps(names)},canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),images={{}};for(const[k,m]of Object.entries(data)){{const im=new Image;im.src=m.file;images[k]=im}}let alt=false;document.querySelector('button').onclick=()=>{{alt=!alt;document.querySelector('#form').textContent=names[alt?1:0];document.querySelector('button').textContent='Preview '+names[alt?0:1]}};function draw(now){{ctx.clearRect(0,0,1000,460);ctx.strokeStyle='#617398';ctx.beginPath();ctx.moveTo(80,420);ctx.lineTo(920,420);ctx.stroke();const key=(alt?'alt_':'')+['idle','walk_a','walk_b','palm','kick','special','crouch','hurt','down'][Math.floor(now/400)%9],m=data[key],im=images[key];if(im.complete)ctx.drawImage(im,500-m.axis[0]*m.scale,420-m.axis[1]*m.scale,im.width*m.scale,im.height*m.scale);requestAnimationFrame(draw)}}requestAnimationFrame(draw)</script></main></html>'''
    signature_html=f'''<article><h2>New signature moves</h2><p>Ground: <kbd>A + C</kbd> together as P1, <kbd>R + H</kbd> as P2. Air: <kbd>A</kbd> as P1, <kbd>R</kbd> as P2. Free, vulnerable moves; hold the ground combination to charge Negan's bat.</p><table><tr><th>Form</th><th>Ground signature</th><th>Air signature</th></tr>{signature_rows}</table><img src="signature-replay-v3.gif" alt="Actual engine capture of both forms' signature moves and unique finisher staging"><p class="small">New native replay: ground signature, air signature, super and ultimate in each form. <a href="signature-preview-report.json">Frame provenance</a>.</p></article>'''
    html=html.replace('<article><h2>Actual transformation',signature_html+'<article><h2>Actual transformation',1)
    html=html.replace('<h2>Both looks at gameplay scale</h2>','<p><a href="../chappelle/scale-review.html">Updated proportions: compare the previous and corrected poses</a></p><h2>Both looks at gameplay scale</h2>',1)
    cinematic_cards=''.join(f'<article><h2>{name}: {row[6]}</h2><img src="../chappelle/{key}-ultimate-v5.gif" alt="Native engine recording of the illustrated {name} ultimate"><p class="small">Illustrated setting, animated contact streaks and landing debris. Recorded from the engine.</p></article>' for name,key,row in zip(names,['prince','rick'] if slug=='prince' else ['tyrone','negan'],moves))
    html=html.replace('<h2>Both looks at gameplay scale</h2>',cinematic_cards+'<h2>Both looks at gameplay scale</h2>',1)
    html=re.sub(r'<article><h2>Actual transformation and combat replay</h2>.*?</article>','',html,flags=re.S)
    if slug=='tyrone':html=html.replace('<a href="signature-preview-report.json">Frame provenance</a>','<a href="signature-preview-report.json">Frame provenance</a> · <a href="../chappelle/negan-execution-preview-report.json">Execution staging checks</a>')
    (source/'review.html').write_text(html,encoding='utf-8')
    cards.append(f'<article><h2>{names[0]} ⇄ {names[1]}</h2><img src="../{slug}/signature-replay-v3.gif" alt="Actual engine replay of signature moves and finishers"><p class="status">{status}</p><a href="../{slug}/review.html">Forms and gameplay</a> · <a href="../{slug}/CONTROLS.md">Controls</a></article>')
hub=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chappelle: two fighters</title><style>{style}</style><main><div class="eyebrow">Corrected Chappelle roster</div><h1>Two fighters. Two forms each.</h1><p><strong>Prince transforms into Rick James.</strong><br><strong>Tyrone Biggums transforms into Negan.</strong></p><p>Press <kbd>W</kbd> as Player 1 or <kbd>]</kbd> as Player 2 to switch to the assigned form and back. Health and meter stay shared.</p><div class="grid">{''.join(cards)}</div><article><h2>Play the paired matchup</h2><p>Open <strong>Play Chappelle Pairs.cmd</strong> in sprite-fighter for Prince (P1) versus Tyrone (P2). Player 1: arrows, Z/X/C attacks, A skill, S super, D ultimate, Q throw, W transform. Player 2: I/J/K/L, F/G/H attacks, R skill, T super, Y ultimate, [ throw, ] transform.</p><p>Play Prince.cmd and Play Tyrone.cmd each start that fighter against inactive Will. Matching CPU and Will-versus shortcuts are also present.</p></article><p class="small"><a href="paired-verification.json">Combined pairing verification</a> · <a href="paired-match-validation.json">Actual two-fighter matchup checks</a>. Previous three-slot packages and reports are archived and superseded.</p></main></html>'''
hub=hub.replace('<div class="grid">','<article><h2>Eight new signature moves</h2><p>Prince: bouncing crossover and aerial skyhook. Rick James: couch surfboard and pogo stomp. Tyrone: pocket sand retreat and zigzag air dash. Negan: charged bat verdict and heavy aerial smash.</p><p>Ground: <kbd>A + C</kbd> as P1 or <kbd>R + H</kbd> as P2. Air: <kbd>A</kbd> as P1 or <kbd>R</kbd> as P2. Each form also has distinct super and ultimate staging.</p></article><div class="grid">',1)
hub=hub.replace('<div class="grid">','<p><a href="scale-review.html">Pose proportions corrected — view the before/after comparison</a></p><div class="grid">',1)
ultimate_cards=''.join(f'<article><h2>{name}</h2><img src="{key}-ultimate-v5.gif" alt="Native recording of {name} ultimate"><p>{description}</p></article>' for key,name,description in [('prince','Prince','Breakfast Is Served: leap up with pancakes, then dunk the plate onto the opponent’s head.'),('rick','Rick James','What did the five fingers say to the face? SLAP!'),('tyrone','Tyrone Biggums','A mist to the face, a dizzy stagger, then the knockout punch.'),('negan','Negan','Night clearing, kneeling captive, deliberate overhead strike and a cut to black.')])
hub=hub.replace('<div class="grid">','<h2>Reworked ultimates</h2><p>Four illustrated settings replace the blocky scenery, oversized props and giant rings. These loops show actual engine gameplay.</p><div class="grid">'+ultimate_cards+'</div><p class="small"><a href="art/cinematics-v5/prompts.json">Exact artwork prompts</a> · Background artwork created with the built-in image generation tool.</p><div class="grid">',1)
hub=hub.replace('Exact artwork prompts</a>','Stage artwork prompts</a> · <a href="art/negan-execution-v1/prompt.txt">Night clearing prompt</a> · <a href="art/finishers-v6/pancake-prompt.txt">Pancake sprite prompt</a>')
(CH/'chappelle/review.html').write_text(hub,encoding='utf-8')
for slug,target in [('rick','prince'),('negan','tyrone')]:
    (CH/slug/'README.md').write_text(f'# Archived standalone component\n\nThis look is now the alternate form of the {target} fighter. [Current pair](../{target}/review.html). The standalone slot is removed from character select; original art and historical reports are retained.\n')
    (CH/slug/'CONTROLS.md').write_text(f'# Alternate form controls\n\nThis look belongs to the {target} fighter. W as Player 1 or ] as Player 2 switches between the assigned forms and back. [Read current paired controls](../{target}/CONTROLS.md). The previous standalone layout is superseded.\n')
    (CH/slug/'review.html').write_text(f'<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../{target}/review.html"><p>This look is now a paired transformation. <a href="../{target}/review.html">Open the current pair</a>.</p>')
print('CHAPPELLE_PAIR_REVIEWS_WRITTEN')
